Your expense tracker is below. Add an item with an amount, a category and a date, and the total and category bars update as you go. Entries stay only while this page is open, so note down the total before you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h2{margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
input{flex:1;min-width:110px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:#e53e3e;padding:4px 8px}
.big{font-size:26px;font-weight:600}
.bar{height:10px;background:#2b6cb0;border-radius:5px}
.track{background:#e2e8f0;border-radius:5px;margin:2px 0 8px}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.muted{color:#666;font-size:12px}
.over{color:#e53e3e}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="row">
    <input id="name" placeholder="What for? (e.g. Milk)">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option>
      <option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button onclick="add()">Add</button>
  </div>
  <div id="msg" class="muted"></div>
</div>
<div class="card">
  <div class="muted">Total this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹, optional)" oninput="render()">
  </div>
  <div id="left" class="muted"></div>
</div>
<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>All entries</b><div id="list"></div></div>
<script>
var items=[];
var fmt=function(n){return '₹'+Math.round(n).toLocaleString('en-IN')};
document.getElementById('date').value=new Date().toISOString().slice(0,10);
function add(){
  var n=document.getElementById('name').value.trim();
  var a=parseFloat(document.getElementById('amt').value);
  if(!n||!(a>0)){document.getElementById('msg').textContent='Add a name and an amount above zero.';return}
  document.getElementById('msg').textContent='';
  items.push({n:n,a:a,c:document.getElementById('cat').value,d:document.getElementById('date').value});
  document.getElementById('name').value='';document.getElementById('amt').value='';
  render();
}
function del(i){items.splice(i,1);render()}
function render(){
  var t=0,by={};
  items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a});
  document.getElementById('total').textContent=fmt(t);
  var b=parseFloat(document.getElementById('budget').value);
  var l=document.getElementById('left');
  if(b>0){
    l.innerHTML=t>b?'<span class="over">Over budget by '+fmt(t-b)+'</span>':fmt(b-t)+' left of '+fmt(b);
  }else l.textContent='';
  var h='';
  Object.keys(by).sort(function(p,q){return by[q]-by[p]}).forEach(function(k){
    var p=t?by[k]/t*100:0;
    h+='<div style="display:flex;justify-content:space-between"><span>'+k+'</span><span>'+fmt(by[k])+' ('+Math.round(p)+'%)</span></div><div class="track"><div class="bar" style="width:'+p+'%"></div></div>';
  });
  document.getElementById('cats').innerHTML=h||'<span class="muted">Nothing yet.</span>';
  var s='';
  items.slice().map(function(x,i){return {x:x,i:i}}).sort(function(p,q){return q.x.d<p.x.d?-1:1}).forEach(function(o){
    var e=o.x;
    s+='<div class="item"><div>'+esc(e.n)+'<div class="muted">'+e.c+' · '+e.d+'</div></div><div>'+fmt(e.a)+' <button class="x" onclick="del('+o.i+')">✕</button></div></div>';
  });
  document.getElementById('list').innerHTML=s||'<div class="muted">No entries yet.</div>';
}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
render();
</script>
</body></html>
```

